"use client";

import {
  type ColumnDef,
  type ColumnFiltersState,
  getCoreRowModel,
  getFilteredRowModel,
  getSortedRowModel,
  type SortingState,
  useReactTable,
} from "@tanstack/react-table";
import { useVirtualizer } from "@tanstack/react-virtual";
import { useCallback, useMemo, useRef, useState } from "react";
import { DataGridEmpty } from "./data-grid-empty";
import { DataGridFilterBar } from "./data-grid-filter-bar";
import { DataGridFooter } from "./data-grid-footer";
import { DataGridSkeleton } from "./data-grid-skeleton";
import { DataGridTable } from "./data-grid-table";
import type { DataGridProps, FilterOperator, FilterRow } from "./types";
import { applyOperator } from "./utils";

function getSortKey<T>(columns: ColumnDef<T, unknown>[], columnId: string): string | undefined {
  const col = columns.find(
    (c) => ("id" in c && c.id === columnId) || ("accessorKey" in c && c.accessorKey === columnId)
  );
  if (!col) return undefined;
  return "accessorKey" in col && typeof col.accessorKey === "string"
    ? col.accessorKey
    : "id" in col && typeof col.id === "string"
      ? col.id
      : undefined;
}

export function DataGrid<T>({
  columns,
  data,
  getRowId,
  isLoading,
  error,
  height = 400,
  showSelectionSummary = true,
  filterableColumns = [],
  controlledState,
  defaultSorting,
}: DataGridProps<T>) {
  const [internalSorting, setInternalSorting] = useState<SortingState>(
    () => defaultSorting ?? []
  );
  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([]);
  const [internalRowSelection, setInternalRowSelection] = useState<
    Record<string, boolean>
  >({});
  const [internalFilterRows, setInternalFilterRows] = useState<FilterRow[]>([]);
  const [currentColumn, setCurrentColumn] = useState(
    filterableColumns[0]?.id ?? ""
  );
  const [currentOperator, setCurrentOperator] = useState<FilterOperator>("contains");
  const [currentValue, setCurrentValue] = useState("");
  const tableContainerRef = useRef<HTMLDivElement>(null);
  const outerContainerRef = useRef<HTMLDivElement>(null);

  const sorting = controlledState?.sorting ?? internalSorting;
  const setSorting = controlledState?.setSorting ?? setInternalSorting;
  const filterRows = controlledState?.filterRows ?? internalFilterRows;
  const setFilterRows = controlledState?.setFilterRows ?? setInternalFilterRows;
  const rowSelection = controlledState?.rowSelection ?? internalRowSelection;
  const setRowSelection =
    controlledState?.setRowSelection ?? setInternalRowSelection;

  const filteredData = useMemo(() => {
    let result = data;
    if (filterRows.length > 0) {
      result = data.filter((row) =>
        filterRows.every((f) => {
          if (!f.value.trim()) return true;
          const col = columns.find(
            (c) => "accessorKey" in c && c.accessorKey === f.columnId
          );
          if (!col || !("accessorKey" in col)) return true;
          const cellValue = String(
            (row as Record<string, unknown>)[col.accessorKey as string] ?? ""
          );
          return applyOperator(cellValue, f.operator, f.value);
        })
      );
    }
    const sortSpec = defaultSorting?.[0];
    if (!sortSpec) return result;
    const key = getSortKey(columns, sortSpec.id);
    if (!key) return result;
    return [...result].sort((a, b) => {
      const aVal = (a as Record<string, unknown>)[key];
      const bVal = (b as Record<string, unknown>)[key];
      const aNum = typeof aVal === "number" ? aVal : NaN;
      const bNum = typeof bVal === "number" ? bVal : NaN;
      const cmp =
        !Number.isNaN(aNum) && !Number.isNaN(bNum)
          ? aNum - bNum
          : String(aVal ?? "").localeCompare(String(bVal ?? ""), undefined, { numeric: true });
      return sortSpec.desc ? -cmp : cmp;
    });
  }, [data, filterRows, columns, defaultSorting]);

  const table = useReactTable<T>({
    data: filteredData,
    columns,
    defaultColumn: {
      filterFn: (row, columnId, filterValue) => {
        const query = String(filterValue ?? "").trim().toLowerCase();
        if (!query) return true;
        return String(row.getValue(columnId) ?? "")
          .toLowerCase()
          .includes(query);
      },
    },
    getRowId: (row, index) => getRowId(row, index),
    state: { sorting, columnFilters, rowSelection },
    onSortingChange: setSorting,
    onColumnFiltersChange: setColumnFilters,
    onRowSelectionChange: setRowSelection,
    enableRowSelection: true,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
  });

  const totalTableWidth = useMemo(
    () => table.getTotalSize(),
    [table.getState().columnSizing, table.getVisibleLeafColumns().length]
  );

  const headerHeight = 44;

  const { rows } = table.getRowModel();
  const rowVirtualizer = useVirtualizer({
    count: rows.length,
    getScrollElement: () => tableContainerRef.current,
    estimateSize: () => 35,
    overscan: 20,
    scrollMargin: headerHeight,
  });
  const virtualRows = rowVirtualizer.getVirtualItems();

  const focusRowAtIndex = useCallback(
    (targetIndex: number) => {
      if (!rows.length || !tableContainerRef.current) return;
      const bounded = Math.max(0, Math.min(targetIndex, rows.length - 1));
      rowVirtualizer.scrollToIndex(bounded, { align: "auto" });
      requestAnimationFrame(() => {
        const rowEl = tableContainerRef.current?.querySelector<HTMLElement>(
          `[data-row-index="${bounded}"]`
        );
        rowEl?.focus();
      });
    },
    [rowVirtualizer, rows.length]
  );

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      const active = document.activeElement as HTMLElement | null;
      const rowIndexAttr = active?.dataset.rowIndex;
      const currentIndex = rowIndexAttr ? Number(rowIndexAttr) : -1;

      if (e.key === "ArrowDown") {
        e.preventDefault();
        focusRowAtIndex(currentIndex + 1);
        return;
      }
      if (e.key === "ArrowUp") {
        e.preventDefault();
        focusRowAtIndex(currentIndex < 0 ? 0 : currentIndex - 1);
        return;
      }
      if (e.key === "Home") {
        e.preventDefault();
        focusRowAtIndex(0);
        return;
      }
      if (e.key === "End") {
        e.preventDefault();
        focusRowAtIndex(rows.length - 1);
        return;
      }
      if (e.key === " " || e.key === "Enter") {
        if (currentIndex < 0) return;
        e.preventDefault();
        rows[currentIndex]?.toggleSelected();
      }
    },
    [focusRowAtIndex, rows]
  );

  const addFilter = useCallback(() => {
    const trimmed = currentValue.trim();
    if (!trimmed || !currentColumn) return;
    setFilterRows((prev) => [
      ...prev,
      {
        id: crypto.randomUUID(),
        columnId: currentColumn,
        operator: currentOperator,
        value: trimmed,
      },
    ]);
    setCurrentValue("");
  }, [currentColumn, currentOperator, currentValue, setFilterRows]);

  const removeActiveFilter = useCallback(
    (id: string) => {
      setFilterRows((prev) => prev.filter((f) => f.id !== id));
    },
    [setFilterRows]
  );

  const clearAllFilters = useCallback(() => {
    setFilterRows([]);
  }, [setFilterRows]);

  if (error) {
    return (
      <div
        data-slot="data-grid-error"
        className="flex items-center justify-center rounded-lg border border-destructive/50 bg-destructive/10 text-destructive"
        style={{ height }}
      >
        {error}
      </div>
    );
  }

  if (isLoading) {
    return (
      <DataGridSkeleton
        columns={columns as ColumnDef<unknown, unknown>[]}
        height={height}
        hasFilterBar={filterableColumns.length > 0}
      />
    );
  }

  if (data.length === 0) {
    return (
      <DataGridEmpty
        height={height}
        hasFilterBar={filterableColumns.length > 0}
      />
    );
  }

  return (
    <div data-slot="data-grid" className="space-y-3">
      {filterableColumns.length > 0 && (
        <DataGridFilterBar
          filterableColumns={filterableColumns}
          currentColumn={currentColumn}
          setCurrentColumn={setCurrentColumn}
          currentOperator={currentOperator}
          setCurrentOperator={setCurrentOperator}
          currentValue={currentValue}
          setCurrentValue={setCurrentValue}
          filterRows={filterRows}
          addFilter={addFilter}
          removeActiveFilter={removeActiveFilter}
          clearAllFilters={clearAllFilters}
        />
      )}

      <DataGridTable<T>
        table={table}
        totalTableWidth={totalTableWidth}
        tableContainerRef={tableContainerRef}
        outerContainerRef={outerContainerRef}
        virtualRows={virtualRows}
        rowVirtualizerTotalSize={rowVirtualizer.getTotalSize()}
        scrollMargin={headerHeight}
        height={height}
        onKeyDown={handleKeyDown}
      />

      {showSelectionSummary && (
        <DataGridFooter
          table={table}
          totalRowCount={data.length}
          showSelectedIds
        />
      )}
    </div>
  );
}

"use client";

import { flexRender, type Table as TableInstance } from "@tanstack/react-table";
import type { VirtualItem } from "@tanstack/react-virtual";
import { ArrowDown, ArrowUp, ChevronsUpDown } from "lucide-react";
import type React from "react";
import { Table, TableBody, TableHeader, TableRow } from "@/components/ui/table";
import { cn } from "@/lib/utils";

export type DataGridTableProps<T> = {
  table: TableInstance<T>;
  totalTableWidth: number;
  tableContainerRef: React.RefObject<HTMLDivElement | null>;
  outerContainerRef: React.RefObject<HTMLDivElement | null>;
  virtualRows: VirtualItem[];
  rowVirtualizerTotalSize: number;
  scrollMargin: number;
  height: number;
  onKeyDown: (e: React.KeyboardEvent) => void;
};

export function DataGridTable<T>({
  table,
  totalTableWidth,
  tableContainerRef,
  outerContainerRef,
  virtualRows,
  rowVirtualizerTotalSize,
  scrollMargin,
  height,
  onKeyDown,
}: DataGridTableProps<T>) {
  const { rows } = table.getRowModel();
  const headerHeight = scrollMargin;

  return (
    <div
      data-slot="data-grid-table"
      ref={(node) => {
        (tableContainerRef as React.MutableRefObject<HTMLDivElement | null>).current = node;
        (outerContainerRef as React.MutableRefObject<HTMLDivElement | null>).current = node;
      }}
      className="data-grid-table-scroll border border-primary bg-background overflow-auto"
      style={{ maxWidth: "100%", height: `${height}px` }}
      onKeyDown={onKeyDown}
    >
      <div
        style={{
          width: `${totalTableWidth}px`,
          minWidth: "100%",
          height: `${headerHeight + rowVirtualizerTotalSize}px`,
          position: "relative",
        }}
      >
        {/* Header: sticky at top, scrolls horizontally with content */}
        <div
          className="sticky top-0 z-10"
          style={{ height: `${headerHeight}px` }}
        >
          <Table
            scrollContainer={false}
            style={{ width: `${totalTableWidth}px`, tableLayout: "fixed" }}
          >
            <TableHeader>
              {table.getHeaderGroups().map((headerGroup) => (
                <TableRow key={headerGroup.id} className="flex w-full">
                  {headerGroup.headers.map((header) => (
                    <th
                      key={header.id}
                      style={{
                        width: header.getSize(),
                        flex: `0 0 ${header.getSize()}px`,
                      }}
                      className="h-11 px-3 text-left align-middle text-sm font-semibold whitespace-nowrap text-primary-foreground"
                    >
                      {header.isPlaceholder ? null : (
                        <div
                          className={cn(
                            "flex items-center gap-1.5 h-full",
                            header.column.getCanSort() &&
                              "cursor-pointer select-none"
                          )}
                          onClick={header.column.getToggleSortingHandler()}
                        >
                          {flexRender(
                            header.column.columnDef.header,
                            header.getContext()
                          )}
                          {header.column.getCanSort() && (
                            <span className="inline-flex shrink-0 text-primary-foreground">
                              {header.column.getIsSorted() === "asc" ? (
                                <ArrowUp className="h-4 w-4" />
                              ) : header.column.getIsSorted() === "desc" ? (
                                <ArrowDown className="h-4 w-4" />
                              ) : (
                                <ChevronsUpDown className="h-4 w-4 opacity-60" />
                              )}
                            </span>
                          )}
                        </div>
                      )}
                    </th>
                  ))}
                </TableRow>
              ))}
            </TableHeader>
          </Table>
        </div>

        {/* Body rows: absolutely positioned within the sized container */}
        <Table
          scrollContainer={false}
          style={{
            width: `${totalTableWidth}px`,
            tableLayout: "fixed",
            position: "absolute",
            top: `${headerHeight}px`,
            left: 0,
          }}
        >
          <TableBody
            style={{
              height: `${rowVirtualizerTotalSize}px`,
              width: "100%",
              position: "relative",
            }}
          >
            {virtualRows.map((virtualItem) => {
              const row = rows[virtualItem.index];
              if (!row) return null;
              return (
                <TableRow
                  key={virtualItem.key}
                  data-row-index={virtualItem.index}
                  tabIndex={0}
                  className="absolute top-0 left-0 flex w-full items-center focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/40"
                  style={{
                    height: `${virtualItem.size}px`,
                    transform: `translateY(${virtualItem.start - scrollMargin}px)`,
                  }}
                  data-state={row.getIsSelected() ? "selected" : undefined}
                  onClick={(e) => {
                    if (
                      (e.target as HTMLElement).closest("button,input")
                    )
                      return;
                    row.toggleSelected();
                  }}
                >
                  {row.getVisibleCells().map((cell) => (
                    <td
                      key={cell.id}
                      style={{
                        width: cell.column.getSize(),
                        flex: `0 0 ${cell.column.getSize()}px`,
                      }}
                      className="p-3 text-sm text-foreground align-middle whitespace-nowrap"
                    >
                      <span className="whitespace-nowrap overflow-hidden text-ellipsis max-w-full block">
                        {flexRender(
                          cell.column.columnDef.cell,
                          cell.getContext()
                        )}
                      </span>
                    </td>
                  ))}
                </TableRow>
              );
            })}
          </TableBody>
        </Table>
      </div>
    </div>
  );
}

"use client";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Search, X } from "lucide-react";
import {
  type FilterOperator,
  type FilterRow,
  FILTER_OPERATORS,
} from "./types";
import { getColumnLabel } from "./utils";

export type DataGridFilterBarProps = {
  filterableColumns: { id: string; label: string }[];
  currentColumn: string;
  setCurrentColumn: (v: string) => void;
  currentOperator: FilterOperator;
  setCurrentOperator: (v: FilterOperator) => void;
  currentValue: string;
  setCurrentValue: (v: string) => void;
  filterRows: FilterRow[];
  addFilter: () => void;
  removeActiveFilter: (id: string) => void;
  clearAllFilters: () => void;
};

export function DataGridFilterBar({
  filterableColumns,
  currentColumn,
  setCurrentColumn,
  currentOperator,
  setCurrentOperator,
  currentValue,
  setCurrentValue,
  filterRows,
  addFilter,
  removeActiveFilter,
  clearAllFilters,
}: DataGridFilterBarProps) {
  return (
    <div data-slot="data-grid-filter-bar" className="space-y-3">
      <div className="flex items-center gap-2">
        <Select value={currentColumn} onValueChange={setCurrentColumn}>
          <SelectTrigger className="w-[140px]">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {filterableColumns.map((col) => (
              <SelectItem key={col.id} value={col.id}>
                {col.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>

        <Select
          value={currentOperator}
          onValueChange={(v) => setCurrentOperator(v as FilterOperator)}
        >
          <SelectTrigger className="w-[130px]">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {FILTER_OPERATORS.map((op) => (
              <SelectItem key={op.value} value={op.value}>
                {op.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>

        <Input
          value={currentValue}
          onChange={(e) => setCurrentValue(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") addFilter();
          }}
          placeholder={`Filter ${getColumnLabel(currentColumn, filterableColumns).toLowerCase()}...`}
          className="flex-1 min-w-[200px]"
        />

        <Button
          type="button"
          size="sm"
          onClick={addFilter}
          className="gap-1.5 shrink-0"
        >
          <Search className="h-3.5 w-3.5" />
          Search
        </Button>
      </div>

      {filterRows.length > 0 && (
        <div className="flex flex-wrap items-center gap-2">
          {filterRows.map((f) => (
            <Badge
              key={f.id}
              variant="outline"
              className="h-7 gap-1.5 pl-2.5 pr-1 text-xs"
            >
              <span className="font-semibold">
                {getColumnLabel(f.columnId, filterableColumns)}
              </span>
              <span className="text-muted-foreground">
                {FILTER_OPERATORS.find((o) => o.value === f.operator)?.label?.toLowerCase()}
              </span>
              <span className="font-mono text-primary">&ldquo;{f.value}&rdquo;</span>
              <button
                type="button"
                onClick={() => removeActiveFilter(f.id)}
                className="ml-0.5 rounded-full p-0.5 hover:bg-destructive/20 hover:text-destructive transition-colors"
              >
                <X className="h-3 w-3" />
              </button>
            </Badge>
          ))}
          {filterRows.length > 1 && (
            <Button
              type="button"
              variant="link"
              size="sm"
              onClick={clearAllFilters}
              className="h-auto p-0 text-xs text-muted-foreground hover:text-destructive"
            >
              Clear all
            </Button>
          )}
        </div>
      )}
    </div>
  );
}

"use client";

import type { Row, Table } from "@tanstack/react-table";
import { SelectedIdsCopy } from "./selected-ids-copy";

export type DataGridFooterProps<T> = {
  table: Table<T>;
  totalRowCount: number;
  showSelectedIds?: boolean;
};

export function DataGridFooter<T>({
  table,
  totalRowCount,
  showSelectedIds = true,
}: DataGridFooterProps<T>) {
  const selectedRows = table.getSelectedRowModel().rows;
  const filteredCount = table.getFilteredRowModel().rows.length;

  return (
    <div data-slot="data-grid-footer" className="space-y-1.5">
      <p className="text-sm text-muted-foreground">
        {selectedRows.length} of {filteredCount} rows selected
        {" · "}
        {totalRowCount.toLocaleString()} total rows
      </p>
      {showSelectedIds && selectedRows.length > 0 && (
        <SelectedIdsCopy ids={selectedRows.map((r: Row<T>) => r.id)} />
      )}
    </div>
  );
}

"use client";

export type DataGridEmptyProps = {
  height: number;
  hasFilterBar: boolean;
};

export function DataGridEmpty({ height, hasFilterBar }: DataGridEmptyProps) {
  return (
    <div data-slot="data-grid-empty" className="space-y-3">
      {hasFilterBar && (
        <div className="flex items-center gap-2 opacity-50 pointer-events-none">
          <div className="h-8 w-[140px] rounded-lg bg-muted" />
          <div className="h-8 w-[130px] rounded-lg bg-muted" />
          <div className="h-8 flex-1 min-w-[200px] rounded-lg bg-muted" />
          <div className="h-8 w-[80px] rounded-lg bg-muted" />
        </div>
      )}
      <div
        className="flex items-center justify-center border border-primary bg-background text-muted-foreground"
        style={{ height }}
      >
        No rows
      </div>
    </div>
  );
}

"use client";

import type { ColumnDef } from "@tanstack/react-table";
import { ROW_HEIGHT } from "./types";

export type DataGridSkeletonProps = {
  columns: ColumnDef<unknown, unknown>[];
  height: number;
  hasFilterBar: boolean;
};

export function DataGridSkeleton({
  columns,
  height,
  hasFilterBar,
}: DataGridSkeletonProps) {
  return (
    <div data-slot="data-grid-skeleton" className="space-y-3">
      {hasFilterBar && (
        <div className="flex items-center gap-2">
          <div className="h-8 w-[140px] rounded-lg bg-muted animate-pulse" />
          <div className="h-8 w-[130px] rounded-lg bg-muted animate-pulse" />
          <div className="h-8 flex-1 min-w-[200px] rounded-lg bg-muted animate-pulse" />
          <div className="h-8 w-[80px] rounded-lg bg-primary/20 animate-pulse" />
        </div>
      )}

      <div className="border border-primary bg-background overflow-hidden">
        <div className="h-11 bg-primary flex items-center gap-3 px-3">
          {columns.map((col, i) => (
            <div
              key={i}
              className="h-3.5 rounded bg-primary-foreground/20 animate-pulse"
              style={{
                width: ("size" in col ? (col.size as number) : 150) * 0.5,
              }}
            />
          ))}
        </div>
        <div>
          {Array.from({ length: Math.floor(height / ROW_HEIGHT) }).map(
            (_, i) => (
              <div
                key={i}
                className="flex items-center gap-3 px-3 border-b border-border/40"
                style={{ height: ROW_HEIGHT }}
              >
                {columns.map((col, j) => (
                  <div
                    key={j}
                    className="h-3 rounded bg-muted animate-pulse"
                    style={{
                      width:
                        ("size" in col ? (col.size as number) : 150) *
                        (0.4 + ((i + j) % 3) * 0.15),
                      animationDelay: `${(i * columns.length + j) * 30}ms`,
                    }}
                  />
                ))}
              </div>
            )
          )}
        </div>
      </div>

      <div className="h-4 w-40 rounded bg-muted animate-pulse" />
    </div>
  );
}

"use client";

import { Check, Copy } from "lucide-react";
import { useCallback, useState } from "react";

export function SelectedIdsCopy({ ids }: { ids: string[] }) {
  const [copied, setCopied] = useState(false);
  const copy = useCallback(() => {
    navigator.clipboard.writeText(ids.join("\n")).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  }, [ids]);
  const preview =
    ids.length <= 3
      ? ids.join(", ")
      : `${ids.slice(0, 2).join(", ")} +${ids.length - 2} more`;
  return (
    <div className="flex items-center gap-2 flex-wrap">
      <span className="text-xs text-muted-foreground">Selected IDs:</span>
      <code className="text-xs font-mono text-foreground/90 bg-muted/60 px-1.5 py-0.5 rounded truncate max-w-md">
        {preview}
      </code>
      <button
        type="button"
        onClick={copy}
        className="inline-flex items-center gap-1 text-xs text-muted-foreground hover:text-foreground transition-colors"
        title="Copy all selected IDs"
      >
        {copied ? (
          <Check className="h-3.5 w-3.5" />
        ) : (
          <Copy className="h-3.5 w-3.5" />
        )}
        {copied ? "Copied" : "Copy IDs"}
      </button>
    </div>
  );
}

import type { ColumnDef } from "@tanstack/react-table";
import type { SortingState } from "@tanstack/react-table";

export const ROW_HEIGHT = 35;

export type FilterOperator = "contains" | "equals" | "startsWith" | "endsWith";

export type FilterRow = {
  id: string;
  columnId: string;
  operator: FilterOperator;
  value: string;
};

export const FILTER_OPERATORS: { value: FilterOperator; label: string }[] = [
  { value: "contains", label: "Contains" },
  { value: "equals", label: "Equals" },
  { value: "startsWith", label: "Starts with" },
  { value: "endsWith", label: "Ends with" },
];

export type DataGridControlledState = {
  sorting: SortingState;
  setSorting: (
    updater: SortingState | ((prev: SortingState) => SortingState)
  ) => void;
  filterRows: FilterRow[];
  setFilterRows: (
    updater: FilterRow[] | ((prev: FilterRow[]) => FilterRow[])
  ) => void;
  rowSelection: Record<string, boolean>;
  setRowSelection: (
    updater:
      | Record<string, boolean>
